begin;
create or replace function public.update_recurring_transaction_rule(p_rule_id uuid,p_type text,p_wallet_id uuid,p_category_id uuid,p_amount numeric,p_note text,p_frequency text,p_start_date date,p_end_date date default null,p_local_time time default '09:00') returns public.recurring_transaction_rules language plpgsql security definer set search_path=public,pg_temp as $$ declare u uuid:=auth.uid();r public.recurring_transaction_rules%rowtype;z text;begin if u is null then raise exception 'Authentication required';end if;if p_type not in('income','expense') or p_frequency not in('weekly','monthly') or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,4) or(p_end_date is not null and p_end_date<p_start_date) then raise exception 'Invalid recurring rule';end if;select * into r from public.recurring_transaction_rules where id=p_rule_id and user_id=u and archived_at is null for update;if not found then raise exception 'Recurring rule not found';end if;z:=public.recurring_tz(u);update public.recurring_transaction_rules set type=p_type::public.category_type,wallet_id=p_wallet_id,category_id=p_category_id,amount=p_amount,note=nullif(trim(p_note),''),frequency=p_frequency::public.recurring_frequency,start_date=p_start_date,end_date=p_end_date,local_time=p_local_time,timezone=z,next_due_at=public.recurring_due(greatest(p_start_date,(now() at time zone z)::date),p_local_time,z),last_error=null where id=r.id returning * into r;while r.next_due_at<=now() loop r.next_due_at:=public.recurring_next(r);end loop;update public.recurring_transaction_rules set next_due_at=r.next_due_at where id=r.id returning * into r;return r;end $$;
revoke all on function public.update_recurring_transaction_rule(uuid,text,uuid,uuid,numeric,text,text,date,date,time) from public;grant execute on function public.update_recurring_transaction_rule(uuid,text,uuid,uuid,numeric,text,text,date,date,time) to authenticated;
commit;
